using UnscRelay.Core;
internal static class LocalAccountInventoryChecks
{
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-account-inventory-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS account inventory: "+label);}try{var spaces=new AccountWorkspaces(root.FullName);var first=spaces.Add("a@example.invalid");var owner=new string('A',64);new AccountSyncStore(spaces.DirectoryFor(first)).Save(new(){Owner=owner,Subject="61616161-6161-4161-8161-616161616161",Activated=false,ErasureRequestId=Guid.NewGuid(),ErasureCapability=new string('A',43),ErasureExecuteAfter=DateTimeOffset.UtcNow.AddDays(-1)});spaces.Select(first);spaces.Remember(new AccountSyncStore(spaces.DirectoryFor(first)).Load());var second=spaces.Add("b@example.invalid");spaces.Select(second);new AccountSyncStore(spaces.DirectoryFor(second)).Save(new(){Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262",Activated=true});Check(new LocalAccountInventory(root.FullName).Accounts().Any(value=>value.Workspace==first&&value.State.ErasureCapability.Length==43),"switching to B retains the inactive pending account A for monitoring");spaces.Forget(first);Check(new LocalAccountInventory(root.FullName).Accounts().Any(value=>value.Workspace==first&&value.State.Owner==owner),"forgetting a disconnected account does not hide its tracked GUID directory");new AccountSyncStore(root.FullName).Save(new(){Owner=new string('C',64),Subject="63636363-6363-4363-8363-636363636363"});Check(new LocalAccountInventory(root.FullName).Accounts().Any(value=>value.Workspace==Guid.Empty),"legacy root identity is inventoried independently of the selected account");Check(!LocalAccountInventory.HasCanonicalIdentity(new(){Owner=new string('B',64),Subject=""}),"a disconnected state with missing subject cannot bypass another owner's pending cleanup failure");Check(LocalAccountInventory.HasCanonicalIdentity(new(){Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262",Activated=false}),"a disconnected account with canonical owner and subject retains its independent identity");var batch=Enumerable.Range(1,17).Select(value=>new LocalAccountEntry(Guid.Parse(value.ToString("x8")+"-0000-4000-8000-000000000000"),root.FullName,new())).ToArray();var reached=new HashSet<Guid>();for(var tick=0;tick<5;tick++)foreach(var entry in new AccountErasurePolling(root.FullName).Next(batch))reached.Add(entry.Workspace);Check(reached.Count==17,"durable fair batches reach the final account even when earlier accounts time out and the host restarts each tick");File.WriteAllText(Path.Combine(root.FullName,"erasure-scan.json"),"{corrupted scheduling cursor");Check(new AccountErasurePolling(root.FullName).Next(batch).Count==4,"malformed scheduling metadata resets without disabling inactive-account checks");File.Delete(Path.Combine(root.FullName,"erasure-scan.json"));var cursorTarget=Path.Combine(root.FullName,"cursor-target.json");File.WriteAllText(cursorTarget,"external sentinel");File.CreateSymbolicLink(Path.Combine(root.FullName,"erasure-scan.json"),cursorTarget);try{new AccountErasurePolling(root.FullName).Next(batch);throw new Exception("Linked polling cursor accepted");}catch(IOException){Check(File.ReadAllText(cursorTarget)=="external sentinel","unsafe cursor links remain refused and their targets untouched");}File.Delete(Path.Combine(root.FullName,"erasure-scan.json"));var foreign=Directory.CreateDirectory(Path.Combine(root.FullName,"foreign-target"));var linked=Path.Combine(root.FullName,"Accounts",Guid.NewGuid().ToString("N"));Directory.CreateSymbolicLink(linked,foreign.FullName);try{new LocalAccountInventory(root.FullName).Accounts();throw new Exception("Linked workspace accepted");}catch(IOException){Check(Directory.Exists(foreign.FullName),"linked GUID workspaces are refused without following their target");}Console.WriteLine("Account inventory checks: "+count);return 0;}finally{root.Delete(true);}}
}
